#include <iostream>
#include <sstream>
#include <string>

int main() {
    std::istringstream entrada{"  riviere\tmontagne\nvallee  "};
    std::string palabra;
    int cantidad = 0;
    while (entrada >> palabra) {
        std::cout << "<" << palabra << ">\n";
        ++cantidad;
    }
    std::cout << "Mots: " << cantidad;
    return 0;
}

#include <iostream>
#include <sstream>
#include <string>

int main() {
    std::istringstream entrada{"  un\n\t  deux-trois "};
    std::string palabra;
    int cantidad = 0;
    while (entrada >> palabra) {
        ++cantidad;
        std::cout << cantidad << ":<" << palabra << ">\n";
    }
    std::cout << "Total: " << cantidad;
    return 0;
}
